-- A `COPY FROM` row enters the table's indexes as an `INSERT`'s does, and an oversized key
-- is refused `54000` with no row landing. The harness compares SQLSTATEs only.
-- @setup
CREATE TABLE ci (a text);
CREATE INDEX ci_i ON ci (a);
-- @copy-from
COPY ci FROM STDIN;
-- @data
ok

-- @verify
SELECT a FROM ci;
